:root {
    --bg-primary: #1a1a2e;
    --bg-secondary: #16213e;
    --bg-hover: #0f3460;
    --text-primary: #eaeaea;
    --text-secondary: #b0b0b0;
    --accent: #00d4ff;
    --accent-hover: #00b8d4;
    --success: #4caf50;
    --error: #ff6b6b;
    --border: #2d3561;
    --shadow: rgba(0, 0, 0, 0.3);
}

html, body {
    height: 100%;
    width: 100%;
}

body {
    background-color: var(--bg-primary);
    color: var(--text-primary);
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, 'Helvetica Neue', Arial, sans-serif;
    line-height: 1.6;
    font-size: 16px;
}

.quiz-container {
    max-width: 700px;
    margin: 0 auto;
    padding: 40px 20px;
    min-height: 100vh;
    display: flex;
    flex-direction: column;
}

.quiz-header {
    text-align: center;
    margin-bottom: 40px;
    animation: fadeIn 0.6s ease-in;
}

.quiz-header h1 {
    font-size: 2.5rem;
    font-weight: 700;
    margin-bottom: 10px;
    background: linear-gradient(135deg, var(--accent), #00a8b5);
    -webkit-background-clip: text;
    -webkit-text-fill-color: transparent;
    background-clip: text;
}

.quiz-subtitle {
    color: var(--text-secondary);
    font-size: 1.1rem;
}

.quiz-form {
    animation: slideUp 0.6s ease-out;
}

.form-field {
    background-color: var(--bg-secondary);
    border: 1px solid var(--border);
    border-radius: 12px;
    padding: 30px;
    margin-bottom: 25px;
    transition: all 0.3s ease;
}

.form-field:hover {
    border-color: var(--accent);
    box-shadow: 0 0 20px rgba(0, 212, 255, 0.1);
}

.question-title {
    font-size: 1.2rem;
    font-weight: 600;
    margin-bottom: 15px;
    color: var(--text-primary);
}

.help-text {
    background-color: var(--bg-primary);
    border-left: 3px solid var(--accent);
    padding: 12px 15px;
    margin-bottom: 20px;
    border-radius: 4px;
    color: var(--text-secondary);
    font-size: 0.95rem;
    line-height: 1.5;
}

.checkbox-group {
    display: flex;
    flex-direction: column;
    gap: 12px;
}

.checkbox-label {
    display: flex;
    align-items: center;
    padding: 12px 15px;
    background-color: var(--bg-primary);
    border: 1px solid var(--border);
    border-radius: 8px;
    cursor: pointer;
    transition: all 0.3s ease;
    user-select: none;
}

.checkbox-label:hover {
    background-color: var(--bg-hover);
    border-color: var(--accent);
    transform: translateX(4px);
}

.checkbox-input {
    appearance: none;
    -webkit-appearance: none;
    -moz-appearance: none;
    width: 20px;
    height: 20px;
    border: 2px solid var(--border);
    border-radius: 4px;
    background-color: var(--bg-primary);
    cursor: pointer;
    transition: all 0.2s ease;
    flex-shrink: 0;
    margin-right: 12px;
    position: relative;
}

.checkbox-input:checked {
    background-color: var(--accent);
    border-color: var(--accent);
    box-shadow: 0 0 10px rgba(0, 212, 255, 0.3);
}

.checkbox-input:checked::after {
    content: '✓';
    position: absolute;
    top: 50%;
    left: 50%;
    transform: translate(-50%, -50%);
    color: var(--bg-primary);
    font-size: 14px;
    font-weight: bold;
}

.checkbox-input:focus-visible {
    outline: 2px solid var(--accent);
    outline-offset: 2px;
}

.label-text {
    color: var(--text-primary);
    font-size: 1rem;
    font-weight: 500;
}

.checkbox-label:has(.checkbox-input:checked) {
    background-color: var(--bg-hover);
    border-color: var(--accent);
}

.submit-button {
    background: linear-gradient(135deg, var(--accent), #00a8b5);
    color: var(--bg-primary);
    border: none;
    padding: 14px 32px;
    font-size: 1.1rem;
    font-weight: 600;
    border-radius: 8px;
    cursor: pointer;
    transition: all 0.3s ease;
    margin-top: 10px;
    text-transform: uppercase;
    letter-spacing: 0.5px;
    box-shadow: 0 4px 15px rgba(0, 212, 255, 0.2);
}

.submit-button:hover {
    transform: translateY(-2px);
    box-shadow: 0 6px 20px rgba(0, 212, 255, 0.3);
}

.submit-button:active {
    transform: translateY(0);
}

.submit-button:focus-visible {
    outline: 2px solid var(--accent);
    outline-offset: 2px;
}

.results-container {
    background-color: var(--bg-secondary);
    border: 1px solid var(--border);
    border-radius: 12px;
    padding: 30px;
    text-align: center;
    animation: slideUp 0.6s ease-out;
}

.results-container h2 {
    font-size: 1.8rem;
    margin-bottom: 20px;
    color: var(--accent);
}

#resultsText {
    font-size: 1rem;
    line-height: 1.8;
    margin-bottom: 25px;
    color: var(--text-secondary);
}

#resultsText strong {
    color: var(--text-primary);
}

.reset-button {
    background-color: var(--bg-primary);
    color: var(--accent);
    border: 2px solid var(--accent);
    padding: 12px 24px;
    font-size: 1rem;
    font-weight: 600;
    border-radius: 8px;
    cursor: pointer;
    transition: all 0.3s ease;
    text-transform: uppercase;
    letter-spacing: 0.5px;
}

.reset-button:hover {
    background-color: var(--accent);
    color: var(--bg-primary);
    transform: translateY(-2px);
}

.reset-button:focus-visible {
    outline: 2px solid var(--accent);
    outline-offset: 2px;
}

.hidden {
    display: none !important;
}

@keyframes fadeIn {
    from {
        opacity: 0;
    }
    to {
        opacity: 1;
    }
}

@keyframes slideUp {
    from {
        opacity: 0;
        transform: translateY(20px);
    }
    to {
        opacity: 1;
        transform: translateY(0);
    }
}

@media (max-width: 600px) {
    .quiz-header h1 {
        font-size: 2rem;
    }

    .form-field {
        padding: 20px;
    }

    .quiz-container {
        padding: 20px 15px;
    }

    .question-title {
        font-size: 1.1rem;
    }
}
